<script>
import CruResource from '@shell/components/CruResource.vue';
import Loading from '@shell/components/Loading.vue';
import Tabbed from '@shell/components/Tabbed/index.vue';
import Tab from '@shell/components/Tabbed/Tab.vue';
import Tolerations from '@shell/components/form/Tolerations';
import LabeledSelect from '@shell/components/form/LabeledSelect.vue';
import CreateEditView from '@shell/mixins/create-edit-view';
import { _CREATE, _EDIT } from '@shell/config/query-params';
import { MANAGEMENT, NORMAN } from '@shell/config/types';
import { Banner } from '@components/Banner';
import { Checkbox } from '@components/Form/Checkbox';
import LabeledInput from '@components/Form/LabeledInput/LabeledInput.vue';
import TextAreaAutoGrow from '@components/Form/TextArea/TextAreaAutoGrow.vue';

export default {
  name: 'ReviewBundleEditView',
  components: {
    Banner,
    Checkbox,
    CruResource,
    LabeledInput,
    LabeledSelect,
    Loading,
    Tabbed,
    Tab,
    TextAreaAutoGrow,
    Tolerations
  },
  mixins: [CreateEditView],
  props: {
    value: {
      type: Object,
      required: true
    },
    mode: {
      type: String,
      required: true
    },
    resource: {
      type: String,
      required: true
    }
  },
  data() {
    if (this.mode === _CREATE) {
      if (!this.value.metadata.name) {
        this.value.metadata.generateName = 'review-bundle';
      }
      if (!this.value.spec) {
        this.value.spec = {};
      }
      this.value.spec.analyzeClusters = ['local'];
      this.value.spec.collectClusters = [];
      this.value.spec.sonobuoyNamespace = 'sonobuoy';
      this.value.spec.httpProxy = '';
      this.value.spec.httpsProxy = '';
      this.value.spec.noProxy = '';
      this.value.spec.enablePrivileged = false;
      this.value.spec.enableDataObfuscation = false;

      this.createApiToken()
        .then((token) => {
          this.value.spec.token = token;
        })
        .catch((error) => {
          console.error(error);
        });

      fetch('/v3/settings/server-url', {
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      })
        .then((response) => {
          if (!response.ok) {
            throw new Error(`HTTP error! Status: ${response.status}`);
          }
          return response.json();
        })
        .then((data) => {
          this.value.spec.hostName = data.value;
        })
        .catch((error) => {
          console.error('Fetch error:', error);
        });

      fetch('/rancherversion', {
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      })
        .then((response) => {
          if (!response.ok) {
            throw new Error(`HTTP error! Status: ${response.status}`);
          }
          return response.json();
        })
        .then((data) => {
          if (data.RancherPrime === 'false') {
            this.value.spec.collectClusters = ['local'];
            this.collectAllClusters = false;
            this.isPrime = false;
          } else {
            this.isPrime = true;
          }
        })
        .catch((error) => {
          console.error('Fetch error:', error);
        });
    }
    return {
      description: '',
      isPrime: true,
      clusterOptions: [],
      loadingClusters: false,
      collectAllClusters: !(this.value?.spec?.collectClusters || []).length
    };
  },
  async fetch() {
    this.loadingClusters = true;
    try {
      const clusters = await this.$store.dispatch('management/findAll', {
        type: MANAGEMENT.CLUSTER
      });

      this.clusterOptions = clusters
        .map((cluster) => ({
          label: cluster.nameDisplay || cluster.id,
          value: cluster.id
        }))
        .sort((a, b) => a.label.localeCompare(b.label));
    } catch (error) {
      console.error('Failed to load clusters:', error);
    } finally {
      this.loadingClusters = false;
    }
  },
  computed: {
    isView() {
      return this.mode !== _CREATE && this.mode !== _EDIT;
    },
    isBundleNameValid() {
      if (this.mode !== _CREATE) {
        return true;
      }

      const name = (this.value.metadata.generateName || '').trim();

      return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/.test(name);
    },
    isFormValid() {
      if (this.isView) {
        return true;
      }

      if (!this.isBundleNameValid) {
        return false;
      }

      if (this.isPrime) {
        return this.collectAllClusters || (this.value.spec.collectClusters || []).length > 0;
      }

      return true;
    },
    editorMode() {
      if (!this.isView) {
        return EDITOR_MODES.EDIT_CODE;
      }

      return EDITOR_MODES.VIEW_CODE;
    },
    hasBeenCreated() {
      return !!this.value.id;
    }
  },
  watch: {
    collectAllClusters(val) {
      if (val) {
        this.value.spec.collectClusters = [];
      }
    }
  },
  methods: {
    async createApiToken() {
      const maxTTLMsec = 4 * 60 * 60 * 1000; // 4 hours

      const token = await this.$store.dispatch('rancher/create', {
        type: NORMAN.TOKEN,
        ttl: maxTTLMsec,
        description: 'Supportability Review'
      });

      const created = await token.save();

      return created.token;
    },
    finishBundle(buttonDone) {
      if (this.mode === _CREATE) {
        this.value.metadata.generateName = `${this.value.metadata.generateName.trim()}-`;
      }

      return this.save(buttonDone);
    },
    setDefaultSonobuoyNamespace() {
      if (!this.value.spec.sonobuoyNamespace.trim()) {
        this.value.spec.sonobuoyNamespace = 'sonobuoy';
      }
    }
  }
};
</script>

<template>
  <Loading v-if="!value" />
  <CruResource
    v-else
    :done-route="doneRoute"
    :can-yaml="true"
    :mode="mode"
    :resource="value"
    :errors="errors"
    :validation-passed="isFormValid"
    @error="(e) => (errors = e)"
    @finish="finishBundle"
    @cancel="done">
    <Tabbed>
      <Tab label-key="sr.menuLabels.basic" name="basic-config" :weight="3">
        <div>
          <h2 class="mb-200">Collector Config</h2>

          <h4 class="mb-200">Bundle Name</h4>
          <LabeledInput
            v-model:value="value.metadata.generateName"
            label="Enter Bundle Name"
            placeholder="review-bundle"
            :maxlength="30"
            :mode="mode" />
          <Banner v-if="!isBundleNameValid" class="mb-10" color="error">
            <div v-clean-html="t('sr.menuLabels.bundleNameRestriction', {}, true)" />
          </Banner>

          <h4 class="mt-20 mb-200">{{ t('sr.menuLabels.collectClusters') }}</h4>
          <Checkbox
            v-model:value="collectAllClusters"
            class="mb-10"
            :mode="mode"
            :disabled="!isPrime"
            :label="t('sr.menuLabels.collectAllClusters')" />
          <template v-if="!collectAllClusters">
            <LabeledSelect
              v-model:value="value.spec.collectClusters"
              :multiple="true"
              :taggable="false"
              :searchable="true"
              :options="clusterOptions"
              :loading="loadingClusters"
              :mode="mode"
              :disabled="!isPrime"
              :label="t('sr.menuLabels.collectClusters')"
              :placeholder="t('sr.menuLabels.collectClustersPlaceholder')" />
            <template v-if="isPrime">
              <Banner v-if="isFormValid" class="mb-10" color="info">
                {{ t('sr.menuLabels.collectClustersHelp') }}
              </Banner>
              <Banner v-else class="mb-10" color="error">
                {{ t('sr.menuLabels.collectClustersRequired') }}
              </Banner>
            </template>
          </template>
          <Banner v-else-if="isPrime" class="mb-10" color="info">
            {{ t('sr.menuLabels.collectAllClustersInfo') }}
          </Banner>
        </div>
      </Tab>
      <Tab label-key="sr.menuLabels.advanced" name="advanced-config" :weight="2">
        <div>
          <h2 class="mb-200">Collector Config</h2>

          <h4 class="mt-10 mb-200">Sonobuoy Namespace</h4>
          <LabeledInput
            v-model:value="value.spec.sonobuoyNamespace"
            placeholder="sonobuoy"
            :maxlength="64"
            :mode="mode"
            @blur="setDefaultSonobuoyNamespace" />
          <Banner class="mb-10" color="warning">
            <div v-clean-html="t('sr.menuLabels.sonobuoyWarning', {}, true)" />
          </Banner>

          <h4 class="mt-10 mb-200" for="tolerations">Tolerations</h4>
          <Tolerations v-model:value="value.spec.tolerations" :mode="mode" />

          <h4 class="mt-10 mb-200">Networking</h4>
          <h6 class="mt-10 mb-200">HTTP proxy</h6>
          <LabeledInput
            v-model:value="value.spec.httpProxy"
            :maxlength="256"
            :mode="mode"
            placeholder="http://proxy.example.com:8080" />
          <h6 class="mt-10 mb-200">HTTPS proxy</h6>
          <LabeledInput
            v-model:value="value.spec.httpsProxy"
            :maxlength="256"
            :mode="mode"
            placeholder="https://proxy.example.com:8080" />
          <h6 class="mt-10 mb-200">No proxy</h6>
          <LabeledInput
            v-model:value="value.spec.noProxy"
            :maxlength="256"
            :mode="mode"
            placeholder=".noproxy.com,127.0.0.1,localhost" />

          <h4 class="mt-10 mb-200">Security</h4>
          <Checkbox
            v-model:value="value.spec.enablePrivileged"
            class="mb-10"
            :mode="mode"
            :label="t('sr.menuLabels.enablePrivileged')" />
          <br />

          <Checkbox
            v-model:value="value.spec.enableDataObfuscation"
            class="mb-10"
            :mode="mode"
            :label="t('sr.menuLabels.enableDataObfuscation')" />

          <h4 class="mt-10 mb-200">Bundle Description</h4>
          <TextAreaAutoGrow
            minHeight="50"
            placeholder="Enter bundle description"
            autocapitalize="off"
            spellcheck="false"
            :mode="mode" />
        </div>
      </Tab>
    </Tabbed>
    <Banner v-if="!isPrime" class="mb-10" color="info">
      <div v-clean-html="t('sr.menuLabels.forCommunityUser0', {}, true)" />
    </Banner>
    <Banner v-if="!isPrime" class="mb-10" color="info">
      <div v-clean-html="t('sr.menuLabels.forCommunityUser1', {}, true)" />
    </Banner>
  </CruResource>
</template>
<style scoped></style>
